#include <vector>
#include <string>
#include <queue>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<std::string> watchedVideosByFriends(std::vector<std::vector<std::string>>& watchedVideos, std::vector<std::vector<int>>& friends, int id, int level) {
        int n = friends.size();
        std::vector<bool> visited(n, false);
        std::queue<int> q;
        q.push(id);
        visited[id] = true;
        int curLevel = 0;
        while (!q.empty() && curLevel < level) {
            int sz = q.size();
            for (int i = 0; i < sz; ++i) {
                int u = q.front();
                q.pop();
                for (int v : friends[u]) {
                    if (!visited[v]) {
                        visited[v] = true;
                        q.push(v);
                    }
                }
            }
            curLevel++;
        }
        std::unordered_map<std::string, int> counts;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (const auto& vid : watchedVideos[u]) counts[vid]++;
        }
        std::vector<std::pair<std::string, int>> items(counts.begin(), counts.end());
        std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
            if (a.second != b.second) return a.second < b.second;
            return a.first < b.first;
        });
        std::vector<std::string> res;
        for (const auto& item : items) res.push_back(item.first);
        return res;
    }
};

import java.util.*;

class Solution {
    public List<String> watchedVideosByFriends(List<List<String>> watchedVideos, int[][] friends, int id, int level) {
        int n = friends.length;
        boolean[] visited = new boolean[n];
        Queue<Integer> q = new LinkedList<>();
        q.offer(id);
        visited[id] = true;
        int curLevel = 0;
        while (!q.isEmpty() && curLevel < level) {
            int sz = q.size();
            for (int i = 0; i < sz; i++) {
                int u = q.poll();
                for (int v : friends[u]) {
                    if (!visited[v]) {
                        visited[v] = true;
                        q.offer(v);
                    }
                }
            }
            curLevel++;
        }
        Map<String, Integer> counts = new HashMap<>();
        while (!q.isEmpty()) {
            int u = q.poll();
            for (String vid : watchedVideos.get(u)) {
                counts.put(vid, counts.getOrDefault(vid, 0) + 1);
            }
        }
        List<String> res = new ArrayList<>(counts.keySet());
        res.sort((a, b) -> {
            int ca = counts.get(a), cb = counts.get(b);
            if (ca != cb) return Integer.compare(ca, cb);
            return a.compareTo(b);
        });
        return res;
    }
}

var watchedVideosByFriends = function(watchedVideos, friends, id, level) {
    const n = friends.length;
    const visited = new Uint8Array(n);
    let q = [id];
    visited[id] = 1;
    let curLevel = 0;
    while (q.length > 0 && curLevel < level) {
        const nextQ = [];
        for (const u of q) {
            for (const v of friends[u]) {
                if (!visited[v]) {
                    visited[v] = 1;
                    nextQ.push(v);
                }
            }
        }
        q = nextQ;
        curLevel++;
    }
    const counts = new Map();
    for (const friend of q) {
        for (const vid of watchedVideos[friend]) {
            counts.set(vid, (counts.get(vid) || 0) + 1);
        }
    }
    return Array.from(counts.keys()).sort((a, b) => {
        const ca = counts.get(a), cb = counts.get(b);
        if (ca !== cb) return ca - cb;
        return a < b ? -1 : (a > b ? 1 : 0);
    });
};
